def solve_dp_N50(N):
    # dp[n][(c_curr, c_prev)] = max_m
    dp = collections.defaultdict(dict)

    for c1 in range(1, N):
        for c2 in range(1, N - c1 + 1):
            dp[c1 + c2][(c2, c1)] = 0

    for n_old in range(2, N):
        for (c_prev, c_pprev), m_old in dp[n_old].items():
            for c_curr in range(1, N - n_old + 1):
                n_new = n_old + c_curr
                new_m = m_old + c_pprev * c_prev * c_curr
                if (c_curr, c_prev) not in dp[n_new] or new_m > dp[n_new][(c_curr, c_prev)]:
                    dp[n_new][(c_curr, c_prev)] = new_m

    max_m = 0
    for n in range(1, N + 1):
        for m in dp[n].values():
            if m > max_m:
                max_m = m
    return max_m

